import { ERROR_CODES, LedgerError } from './errors.mjs';

export class BatchIngestor {
  #maxBatchSize;
  #sinkFn;
  #buffer;
  #committedWatermarkSeq;
  #totalCommitted;

  /**
   * @param {{ maxBatchSize?: number, sinkFn: (batch: Array<object>) => Promise<void> }} options
   */
  constructor(options = {}) {
    if (typeof options.sinkFn !== 'function') {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'sinkFn must be a function');
    }
    const maxBatchSize = options.maxBatchSize ?? 50;
    if (!Number.isInteger(maxBatchSize) || maxBatchSize < 1) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'maxBatchSize must be positive integer');
    }
    this.#maxBatchSize = maxBatchSize;
    this.#sinkFn = options.sinkFn;
    this.#buffer = [];
    this.#committedWatermarkSeq = 0;
    this.#totalCommitted = 0;
  }

  /**
   * Buffers one event and triggers a flush if `maxBatchSize` is reached.
   *
   * @param {{ seq: number, metric: string, units: number }} event
   */
  async ingest(event) {
    if (!event || !Number.isInteger(event.seq) || typeof event.metric !== 'string') {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_EVENT, 'Event must have integer seq and string metric');
    }
    this.#buffer.push({ ...event });
    if (this.#buffer.length >= this.#maxBatchSize) {
      await this.flush();
    }
  }

  /**
   * Flushes all buffered events through `sinkFn`.
   */
  async flush() {
    if (this.#buffer.length === 0) return { flushedCount: 0 };
    const batch = this.#buffer.splice(0, this.#buffer.length);
    await this.#sinkFn(batch);
    for (const item of batch) {
      if (item.seq > this.#committedWatermarkSeq) {
        this.#committedWatermarkSeq = item.seq;
      }
    }
    this.#totalCommitted += batch.length;
    return { flushedCount: batch.length };
  }

  get pendingCount() {
    return this.#buffer.length;
  }

  get committedWatermarkSeq() {
    return this.#committedWatermarkSeq;
  }

  get totalCommitted() {
    return this.#totalCommitted;
  }
}
import { DEFAULT_TIME_ZONE } from './constants.mjs';
import { ERROR_CODES, LedgerError } from './errors.mjs';

const DAY_MS = 86_400_000;

function extractLocalParts(utcMs, timeZone) {
  let fmt;
  try {
    fmt = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  } catch (err) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIMEZONE, `Invalid timeZone: ${timeZone}`, { cause: err.message });
  }
  const parts = {};
  for (const p of fmt.formatToParts(new Date(utcMs))) {
    if (p.type !== 'literal') {
      parts[p.type] = Number(p.value);
    }
  }
  return parts;
}

function getOffsetMs(utcMs, timeZone) {
  const p = extractLocalParts(utcMs, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - Math.floor(utcMs / 1000) * 1000;
}

/**
 * Returns the billing window [startUtcMs, endUtcMs) containing `utcMs`
 * for the given IANA `timeZone` and local day anchor hour (`0..23`).
 *
 * NOTE: Naive implementation assumes fixed 24h offset from `utcMs`.
 *
 * @param {number} utcMs
 * @param {string} [timeZone='UTC']
 * @param {number} [anchorHourLocal=0]
 * @returns {{ startUtcMs: number, endUtcMs: number, localDate: string, timeZone: string }}
 */
export function getBillingWindowBounds(utcMs, timeZone = DEFAULT_TIME_ZONE, anchorHourLocal = 0) {
  if (!Number.isFinite(utcMs)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'utcMs must be finite');
  }
  if (!Number.isInteger(anchorHourLocal) || anchorHourLocal < 0 || anchorHourLocal > 23) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'anchorHourLocal must be integer 0..23');
  }
  const parts = extractLocalParts(utcMs, timeZone);
  const offsetMs = getOffsetMs(utcMs, timeZone);
  const anchorWallAsUtc = Date.UTC(parts.year, parts.month - 1, parts.day, anchorHourLocal, 0, 0);
  let startUtcMs = anchorWallAsUtc - offsetMs;
  if (utcMs < startUtcMs) {
    startUtcMs -= DAY_MS;
  }
  const endUtcMs = startUtcMs + DAY_MS;
  const startParts = extractLocalParts(startUtcMs, timeZone);
  const localDate = `${String(startParts.year).padStart(4, '0')}-${String(startParts.month).padStart(2, '0')}-${String(startParts.day).padStart(2, '0')}`;
  return {
    startUtcMs,
    endUtcMs,
    localDate,
    timeZone
  };
}

/**
 * Enumerates daily billing windows covering [startUtcMs, endUtcMs).
 *
 * @param {number} startUtcMs
 * @param {number} endUtcMs
 * @param {string} [timeZone='UTC']
 * @param {number} [anchorHourLocal=0]
 */
export function enumerateDailyWindows(startUtcMs, endUtcMs, timeZone = DEFAULT_TIME_ZONE, anchorHourLocal = 0) {
  if (!Number.isFinite(startUtcMs) || !Number.isFinite(endUtcMs) || endUtcMs < startUtcMs) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'Invalid window range');
  }
  if (startUtcMs === endUtcMs) return [];
  const windows = [];
  let cursor = getBillingWindowBounds(startUtcMs, timeZone, anchorHourLocal);
  while (cursor.startUtcMs < endUtcMs) {
    windows.push(cursor);
    cursor = {
      ...getBillingWindowBounds(cursor.endUtcMs, timeZone, anchorHourLocal),
      startUtcMs: cursor.endUtcMs,
      endUtcMs: cursor.endUtcMs + DAY_MS
    };
  }
  return windows;
}
export const SUPPORTED_CURRENCIES = Object.freeze(['USD', 'EUR', 'GBP']);

export const INVOICE_STATUS = Object.freeze({
  DRAFT: 'DRAFT',
  FINALIZED: 'FINALIZED',
  VOIDED: 'VOIDED'
});

export const ROUNDING_MODES = Object.freeze({
  HALF_AWAY_FROM_ZERO: 'HALF_AWAY_FROM_ZERO',
  FLOOR: 'FLOOR'
});

export const MAX_BPS = 10_000;
export const WIRE_SCHEMA_VERSION = 'LP-WIRE-V1';
export const DEFAULT_TIME_ZONE = 'UTC';
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Applies available credit grants to a positive charge amount in cents.
 *
 * @param {number} chargeCents
 * @param {Array<{ grantId: string, remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 * @returns {{ appliedCents: number, remainingChargeCents: number, allocations: Array<{ grantId: string, appliedCents: number }>, updatedGrants: Array<object> }}
 */
export function applyCredits(chargeCents, grants = [], asOfMs = 0) {
  if (!Number.isFinite(chargeCents)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_AMOUNT, 'chargeCents must be finite');
  }
  if (!Array.isArray(grants)) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_CONFIG, 'grants must be an array');
  }

  let remaining = chargeCents;
  let appliedCents = 0;
  const allocations = [];

  for (const grant of grants) {
    if (remaining <= 0) break;
    if (!grant || grant.remainingCents <= 0) continue;
    const take = Math.min(remaining, grant.remainingCents);
    grant.remainingCents -= take;
    remaining -= take;
    appliedCents += take;
    allocations.push({ grantId: grant.grantId, appliedCents: take });
  }

  return {
    appliedCents,
    remainingChargeCents: remaining,
    allocations,
    updatedGrants: grants
  };
}

/**
 * Summarizes total remaining cents across credit grants.
 *
 * @param {Array<{ remainingCents: number, effectiveFromMs: number, expiresAtMs: number }>} grants
 * @param {number} asOfMs
 */
export function summarizePoolBalance(grants = [], asOfMs = 0) {
  let availableCents = 0;
  let activeCount = 0;
  for (const g of grants) {
    if (g && g.remainingCents > 0) {
      availableCents += g.remainingCents;
      activeCount += 1;
    }
  }
  return { availableCents, activeCount, asOfMs };
}
export const ERROR_CODES = Object.freeze({
  ERR_NEGATIVE_UNITS: 'ERR_NEGATIVE_UNITS',
  ERR_INVALID_TIERS: 'ERR_INVALID_TIERS',
  ERR_INVALID_AMOUNT: 'ERR_INVALID_AMOUNT',
