export class LedgerError extends Error {
  /**
   * @param {string} code
   * @param {string} message
   * @param {object} [details]
   */
  constructor(code, message, details = undefined) {
    super(message);
    this.name = 'LedgerError';
    this.code = code;
    if (details !== undefined) {
      this.details = details;
    }
  }
}
import { WIRE_SCHEMA_VERSION } from './constants.mjs';

/**
 * Legacy LP-WIRE-V1 deterministic 32-bit FNV-1a digest serializer.
 * FROZEN CONTRACT: downstream settlement consumers rely on exact byte output.
 *
 * @param {object} summary
 * @returns {string}
 */
export function encodeFrozenWireDigest(summary = {}) {
  const invoiceId = String(summary.invoiceId || '');
  const accountId = String(summary.accountId || '');
  const currency = String(summary.currency || 'USD');
  const totalDueCents = Math.trunc(Number(summary.totalDueCents || 0));
  const status = String(summary.status || 'FINALIZED');
  const canonical = `${WIRE_SCHEMA_VERSION}|${invoiceId}|${accountId}|${currency}|${totalDueCents}|${status}`;

  let hash = 0x811c9dc5;
  for (let i = 0; i < canonical.length; i += 1) {
    hash ^= canonical.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  const hex = (hash >>> 0).toString(16).padStart(8, '0');
  return `${WIRE_SCHEMA_VERSION}:${hex}:${totalDueCents}`;
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

export class IdempotencyGuard {
  #ttlMs;
  #maxEntries;
  #entries;

  /**
   * @param {{ ttlMs?: number, maxEntries?: number }} [options]
   */
  constructor(options = {}) {
    this.#ttlMs = options.ttlMs ?? 60_000;
    this.#maxEntries = options.maxEntries ?? 1000;
    this.#entries = new Map();
  }

  /**
   * Records or checks an idempotency key.
   *
   * @param {string} key
   * @param {string} payloadHash
   * @param {number} nowMs
   * @returns {{ status: 'accepted' | 'duplicate', key: string, expiresAtMs: number, originalRecordedAtMs: number }}
   */
  checkAndRecord(key, payloadHash, nowMs) {
    if (!key || typeof key !== 'string') {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_EVENT, 'Idempotency key must be a non-empty string');
    }
    if (!Number.isFinite(nowMs)) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_EVENT, 'nowMs must be finite');
    }

    const existing = this.#entries.get(key);
    if (existing) {
      if (existing.payloadHash !== payloadHash) {
        throw new LedgerError(
          ERROR_CODES.ERR_IDEMPOTENCY_CONFLICT,
          `Payload hash mismatch for key ${key}`
        );
      }
      if (nowMs <= existing.expiresAtMs) {
        return {
          status: 'duplicate',
          key,
          expiresAtMs: existing.expiresAtMs,
          originalRecordedAtMs: existing.recordedAtMs
        };
      }
    }

    const entry = {
      payloadHash,
      recordedAtMs: nowMs,
      expiresAtMs: nowMs + this.#ttlMs
    };
    this.#entries.set(key, entry);
    return {
      status: 'accepted',
      key,
      expiresAtMs: entry.expiresAtMs,
      originalRecordedAtMs: entry.recordedAtMs
    };
  }

  /**
   * Removes expired keys as of `nowMs` and returns count removed.
   *
   * @param {number} nowMs
   * @returns {number}
   */
  pruneExpired(nowMs) {
    let removed = 0;
    for (const [key, entry] of this.#entries.entries()) {
      if (nowMs > entry.expiresAtMs) {
        this.#entries.delete(key);
        removed += 1;
      }
    }
    return removed;
  }

  get size() {
    return this.#entries.size;
  }
}
import { INVOICE_STATUS } from './constants.mjs';
import { computeGraduatedCharge } from './tierEngine.mjs';
import { applyCredits } from './creditPool.mjs';
import { encodeFrozenWireDigest } from './frozenWire.mjs';

/**
 * Builds an invoice from usage rows and credit grants.
 *
 * @param {object} params
 * @returns {object}
 */
export function buildInvoice({
  invoiceId,
  accountId,
  currency = 'USD',
  usageRows = [],
  grants = [],
  asOfMs = 0
} = {}) {
  const lineItems = [];
  let usageSubtotalCents = 0;

  for (const row of usageRows) {
    const { totalCents } = computeGraduatedCharge(row.units, row.tiers);
    usageSubtotalCents += totalCents;
    lineItems.push({
      metric: row.metric,
      units: row.units,
      amountCents: totalCents
    });
  }

  const creditResult = applyCredits(usageSubtotalCents, grants, asOfMs);
  const totalDueCents = creditResult.remainingChargeCents;
  const status = INVOICE_STATUS.FINALIZED;
  const wireDigest = encodeFrozenWireDigest({
    invoiceId,
    accountId,
    currency,
    totalDueCents,
    status
  });

  return {
    invoiceId,
    accountId,
    currency,
    status,
    lineItems,
    usageSubtotalCents,
    appliedCreditsCents: creditResult.appliedCents,
    creditAllocations: creditResult.allocations,
    totalDueCents,
    wireDigest
  };
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Tokenizes a filter expression into typed tokens.
 *
 * @param {string} expr
 * @returns {Array<{ type: string, value: any }>}
 */
export function tokenizeDsl(expr) {
  if (typeof expr !== 'string' || !expr.trim()) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Filter expression must be a non-empty string');
  }
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }
    if (ch === '(' || ch === ')' || ch === ',') {
      tokens.push({ type: ch, value: ch });
      i += 1;
      continue;
    }
    if (ch === '"') {
      let j = i + 1;
      let buf = '';
      while (j < expr.length) {
        if (expr[j] === '"' && expr[j - 1] !== '\\') break;
        buf += expr[j];
        j += 1;
      }
      if (j >= expr.length) {
        throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unterminated string literal');
      }
      tokens.push({ type: 'STRING', value: buf });
      i = j + 1;
      continue;
    }
    const two = expr.slice(i, i + 2);
    if (two === '==' || two === '!=' || two === '>=' || two === '<=') {
      tokens.push({ type: 'OP', value: two });
      i += 2;
      continue;
    }
    if (ch === '>' || ch === '<') {
      tokens.push({ type: 'OP', value: ch });
      i += 1;
      continue;
    }
    if (/[0-9-]/.test(ch)) {
      const m = /^-?\d+(?:\.\d+)?/.exec(expr.slice(i));
      if (m) {
        tokens.push({ type: 'NUMBER', value: Number(m[0]) });
        i += m[0].length;
        continue;
      }
    }
    const ident = /^[A-Za-z_][A-Za-z0-9_.]*/.exec(expr.slice(i));
    if (ident) {
      const word = ident[0];
      const upper = word.toUpperCase();
      if (upper === 'AND' || upper === 'OR' || upper === 'NOT') {
        tokens.push({ type: upper, value: upper });
      } else if (upper === 'TRUE' || upper === 'FALSE') {
        tokens.push({ type: 'BOOLEAN', value: upper === 'TRUE' });
      } else if (upper === 'NULL') {
        tokens.push({ type: 'NULL', value: null });
      } else {
        tokens.push({ type: 'IDENT', value: word });
      }
      i += word.length;
      continue;
    }
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected character: ${ch}`);
  }
  return tokens;
}

function resolveField(obj, pathStr) {
  const parts = String(pathStr).split('.');
  let cur = obj;
  for (const part of parts) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    cur = cur[part];
  }
  return cur;
}

/**
 * Compiles a filter expression string into `(event) => boolean`.
 *
 * @param {string} expr
 * @returns {(event: object) => boolean}
 */
export function compileFilter(expr) {
  const tokens = tokenizeDsl(expr);
  let pos = 0;

  function peek() {
    return tokens[pos] || null;
  }

  function consume(expectedType = null) {
    const tok = tokens[pos];
    if (!tok || (expectedType && tok.type !== expectedType)) {
      throw new LedgerError(
        ERROR_CODES.ERR_DSL_SYNTAX,
        `Expected ${expectedType || 'token'}, got ${tok ? tok.type : 'EOF'}`
      );
    }
    pos += 1;
    return tok;
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, 'Unexpected end of filter');
    if (tok.type === '(') {
      consume('(');
      const inner = parseExpr();
      consume(')');
      return inner;
    }
    if (tok.type === 'NOT') {
      consume('NOT');
      const inner = parsePrimary();
      return (evt) => !inner(evt);
    }
    const fieldTok = consume('IDENT');
    const opTok = consume('OP');
    const valTok = consume();
    if (!['STRING', 'NUMBER', 'BOOLEAN', 'NULL'].includes(valTok.type)) {
      throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected literal token: ${valTok.type}`);
    }
    const target = valTok.value;
    return (evt) => {
      const actual = resolveField(evt, fieldTok.value);
      switch (opTok.value) {
        case '==': return actual === target;
        case '!=': return actual !== target;
        case '>': return actual > target;
        case '>=': return actual >= target;
        case '<': return actual < target;
        case '<=': return actual <= target;
        default: return false;
      }
    };
  }

  function parseExpr() {
    let left = parsePrimary();
    while (peek() && (peek().type === 'AND' || peek().type === 'OR')) {
      const op = consume().type;
      const right = parsePrimary();
      const prevLeft = left;
      left = op === 'AND'
        ? (evt) => prevLeft(evt) && right(evt)
        : (evt) => prevLeft(evt) || right(evt);
    }
    return left;
  }

  const fn = parseExpr();
  if (pos !== tokens.length) {
    throw new LedgerError(ERROR_CODES.ERR_DSL_SYNTAX, `Unexpected trailing token ${tokens[pos].value}`);
  }
  return fn;
}
import { ERROR_CODES, LedgerError } from './errors.mjs';

/**
 * Computes graduated (marginal/tiered) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, breakdown: Array<{ tierIndex: number, upTo: number | null, units: number, unitRateCents: number, subtotalCents: number }> }}
 */
export function computeGraduatedCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    return { totalCents: 0, breakdown: [] };
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    if (units <= prevUpTo && i > 0) break;

    const bounded = Math.min(units, cap);
    const bandUnits = Math.max(0, bounded - prevUpTo + (prevUpTo > 0 ? 1 : 0));
    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    totalCents += subtotalCents;
    breakdown.push({
      tierIndex: i,
      upTo: cap === Infinity ? null : cap,
      units: bandUnits,
      unitRateCents: tier.unitRateCents,
      subtotalCents
    });
    if (cap === Infinity) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}

/**
 * Computes volume (all-units-at-matched-tier-rate) usage charges.
 *
 * @param {number} units
 * @param {Array<{ upTo: number | null, unitRateCents: number }>} tiers
 * @returns {{ totalCents: number, matchedTierIndex: number, unitRateCents: number }}
 */
export function computeVolumeCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be >= 0');
  }
  if (units === 0) {
    return { totalCents: 0, matchedTierIndex: 0, unitRateCents: tiers[0].unitRateCents };
  }

  for (let i = 0; i < tiers.length; i += 1) {
    const cap = tiers[i].upTo === null || tiers[i].upTo === undefined ? Infinity : tiers[i].upTo;
    if (units <= cap) {
      return {
        totalCents: Math.round(units * tiers[i].unitRateCents),
        matchedTierIndex: i,
        unitRateCents: tiers[i].unitRateCents
      };
    }
  }
  const lastIdx = tiers.length - 1;
  return {
    totalCents: Math.round(units * tiers[lastIdx].unitRateCents),
    matchedTierIndex: lastIdx,
    unitRateCents: tiers[lastIdx].unitRateCents
  };
}
