import fs from 'node:fs';
const f = 'src/tierEngine.mjs';
let s = fs.readFileSync(f, 'utf8');
const start = s.indexOf('export function computeGraduatedCharge');
const end = s.indexOf('/**\n * Computes volume');
const fn = `export function computeGraduatedCharge(units, tiers) {
  if (!Array.isArray(tiers) || tiers.length === 0) {
    throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tiers must be a non-empty array');
  }
  if (!Number.isFinite(units) || units < 0) {
    throw new LedgerError(ERROR_CODES.ERR_NEGATIVE_UNITS, 'units must be a finite number >= 0');
  }

  let prevCap = 0;
  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    if (!tier || typeof tier !== 'object' || !Number.isFinite(tier.unitRateCents) || tier.unitRateCents < 0) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, \`tier \${i} must have finite unitRateCents >= 0\`);
    }
    const open = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity;
    if (open) {
      if (i !== tiers.length - 1) {
        throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'only the last tier may be open-ended');
      }
    } else if (!Number.isFinite(tier.upTo) || tier.upTo <= prevCap) {
      throw new LedgerError(ERROR_CODES.ERR_INVALID_TIERS, 'tier upTo values must be strictly increasing');
    } else {
      prevCap = tier.upTo;
    }
  }

  let prevUpTo = 0;
  let totalCents = 0;
  const breakdown = [];

  for (let i = 0; i < tiers.length; i += 1) {
    const tier = tiers[i];
    const cap = tier.upTo === null || tier.upTo === undefined || tier.upTo === Infinity ? Infinity : tier.upTo;
    if (units <= prevUpTo && i > 0) break;

    const bandUnits = Math.max(0, Math.min(units, cap) - prevUpTo);
    const subtotalCents = Math.floor(bandUnits * tier.unitRateCents);
    totalCents += subtotalCents;
    breakdown.push({
      tierIndex: i,
      upTo: cap === Infinity ? null : cap,
      units: bandUnits,
      unitRateCents: tier.unitRateCents,
      subtotalCents
    });
    if (cap === Infinity) break;
    prevUpTo = cap;
  }

  return { totalCents, breakdown };
}

`;
s = s.slice(0, start) + fn + s.slice(end);
fs.writeFileSync(f, s);
